const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define ROI - agricultural area between Kakhovka and North Crimean Canals in Ukraine
  const roi = ee.Geometry.Polygon([
    [33.5, 46.8],
    [34.2, 46.8], 
    [34.2, 46.3],
    [33.5, 46.3],
    [33.5, 46.8]
  ]);

  // Date ranges (±3 days for cloud-free images)
  const mayDate = ee.Date('2023-05-17');
  const juneDate = ee.Date('2023-06-18');
  const dateRange = 3; // days

  // Function to get cloud-masked Sentinel-2 image
  function getCloudFreeImage(targetDate) {
    const startDate = targetDate.advance(-dateRange, 'day');
    const endDate = targetDate.advance(dateRange, 'day');

    const collection = ee.ImageCollection('COPERNICUS/S2_SR')
      .filterBounds(roi)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

    return collection.median()
      .updateMask(collection.count().gt(0))
      .clip(roi);
  }

  // Function to calculate NDVI
  function addNDVI(image) {
    const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return image.addBands(ndvi);
  }

  // Get images for both periods
  const mayImage = getCloudFreeImage(mayDate);
  const juneImage = getCloudFreeImage(juneDate);

  // Check if collections have data
  const mayCount = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(roi)
    .filterDate(mayDate.advance(-dateRange, 'day'), mayDate.advance(dateRange, 'day'))
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30))
    .size();

  const juneCount = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(roi)
    .filterDate(juneDate.advance(-dateRange, 'day'), juneDate.advance(dateRange, 'day'))
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30))
    .size();

  const maySize = mayCount.getInfo();
  const juneSize = juneCount.getInfo();

  console.log(`May images: ${maySize}, June images: ${juneSize}`);

  if (maySize === 0 || juneSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Process images and calculate NDVI
  const mayNDVI = addNDVI(mayImage).select('NDVI');
  const juneNDVI = addNDVI(juneImage).select('NDVI');

  // Calculate mean NDVI and pixel counts
  const mayStats = mayNDVI.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: roi,
    scale: 100,
    maxPixels: 1e9
  });

  const juneStats = juneNDVI.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: roi,
    scale: 100,
    maxPixels: 1e9
  });

  const mayResult = mayStats.getInfo();
  const juneResult = juneStats.getInfo();

  console.log(`May NDVI: ${mayResult.NDVI ? mayResult.NDVI.toFixed(3) : 'NaN'}, Pixels: ${mayResult.NDVI_count}`);
  console.log(`June NDVI: ${juneResult.NDVI ? juneResult.NDVI.toFixed(3) : 'NaN'}, Pixels: ${juneResult.NDVI_count}`);

  // Check for valid pixels
  if (mayResult.NDVI_count === 0 || juneResult.NDVI_count === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation failures
  if (mayResult.NDVI === null || juneResult.NDVI === null || 
      isNaN(mayResult.NDVI) || isNaN(juneResult.NDVI)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare NDVI values (lower NDVI = browner)
  if (juneResult.NDVI < mayResult.NDVI) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
